-- incoming_remote_target_id/incoming_remote_principal_id stamp the caller's stable transport identity (enrolled target + caller principal bound by the admitting enrollment scope), not an ephemeral boot handle.
CREATE TABLE runs(scope TEXT NOT NULL,id TEXT NOT NULL,target_id TEXT NOT NULL,root_run_id TEXT NOT NULL,parent_run_id TEXT NOT NULL,call_node_id TEXT NOT NULL,depth INTEGER NOT NULL CHECK(depth>=0),session_id TEXT NOT NULL,session_instance_id TEXT NOT NULL CHECK(length(CAST(session_instance_id AS BLOB))<=512),idempotency_key TEXT NOT NULL,predecessor_run_id TEXT NOT NULL DEFAULT '',workflow_resource_id TEXT NOT NULL,workflow_commit_id TEXT NOT NULL,definition_digest TEXT NOT NULL,action_id TEXT NOT NULL,inputs_json BLOB NOT NULL,trigger_json BLOB NOT NULL,source_observation_json BLOB NOT NULL,status TEXT NOT NULL CHECK(status IN ('queued','running','stopping','succeeded','failed','stopped','canceled','interrupted')),termination TEXT NOT NULL,error_json BLOB NOT NULL,error_summary_json BLOB NOT NULL,result_json BLOB NOT NULL,nodes_json BLOB NOT NULL,cleanup_errors_json BLOB NOT NULL,cleanup_failed INTEGER NOT NULL CHECK(cleanup_failed>=0),created_at INTEGER NOT NULL,started_at INTEGER NOT NULL,finished_at INTEGER NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),bytes INTEGER NOT NULL CHECK(bytes>=0),pending_remote_count INTEGER NOT NULL DEFAULT 0 CHECK(pending_remote_count BETWEEN 0 AND 1024),pending_remote_bytes INTEGER NOT NULL DEFAULT 0 CHECK(pending_remote_bytes BETWEEN 0 AND 524288),retention_local_ok INTEGER NOT NULL DEFAULT 0 CHECK(retention_local_ok IN (0,1) AND (retention_local_ok=0 OR finished_at>0)),retention_eligible INTEGER NOT NULL DEFAULT 0 CHECK(retention_eligible IN (0,1) AND retention_eligible<=retention_local_ok),incoming_remote_target_id TEXT NOT NULL DEFAULT '',incoming_remote_principal_id TEXT NOT NULL DEFAULT '',incoming_hold_released INTEGER NOT NULL DEFAULT 0 CHECK(incoming_hold_released IN (0,1)),source_experiment_id TEXT GENERATED ALWAYS AS (coalesce(json_extract(CASE WHEN length(source_observation_json)>0 THEN CAST(source_observation_json AS TEXT) ELSE '{}' END,'$.experimentInvocation.experimentId'),'')) STORED,source_instance_id TEXT GENERATED ALWAYS AS (coalesce(json_extract(CASE WHEN length(source_observation_json)>0 THEN CAST(source_observation_json AS TEXT) ELSE '{}' END,'$.experimentInvocation.workflowInstanceId'),'')) STORED,PRIMARY KEY(scope,id),CHECK((status IN ('queued','running','stopping'))=(finished_at=0)),CHECK((pending_remote_count=0)=(pending_remote_bytes=0)),CHECK(predecessor_run_id = '' OR (predecessor_run_id <> id AND parent_run_id = '' AND depth = 0)),CHECK((incoming_remote_target_id='')=(incoming_remote_principal_id='')),CHECK(incoming_remote_target_id='' OR (parent_run_id<>'' AND incoming_remote_target_id<>target_id)),CHECK(incoming_hold_released=0 OR incoming_remote_target_id<>''));
CREATE UNIQUE INDEX runs_idempotency ON runs(scope,idempotency_key) WHERE idempotency_key<>'';
CREATE INDEX runs_created ON runs(scope,created_at,id);
CREATE INDEX runs_target ON runs(scope,target_id,created_at,id);
CREATE INDEX runs_root ON runs(scope,root_run_id,created_at,id);
CREATE INDEX runs_session ON runs(scope,session_id,created_at,id) WHERE session_id<>'';
CREATE INDEX runs_session_instance ON runs(scope,session_id,session_instance_id,created_at,id) WHERE session_id<>'';
CREATE INDEX runs_session_instance_open ON runs(scope,session_id,session_instance_id,created_at,id) WHERE session_id<>'' AND status IN ('queued','running','stopping');
CREATE INDEX runs_session_pending ON runs(scope,session_id,id) WHERE session_id<>'' AND pending_remote_count>0;
CREATE INDEX runs_session_failed ON runs(scope,session_id,id) WHERE session_id<>'' AND cleanup_failed>0;
CREATE INDEX runs_workflow ON runs(scope,workflow_resource_id,created_at,id);
CREATE INDEX runs_open ON runs(scope,created_at,id) WHERE status IN ('queued','running','stopping');
CREATE INDEX runs_retention_eligible ON runs(scope,finished_at,id) WHERE retention_eligible=1;
CREATE INDEX runs_retention_root_group ON runs(scope,root_run_id,retention_local_ok,retention_eligible,target_id,session_id,id) WHERE finished_at>0;
CREATE INDEX runs_retention_session_group ON runs(scope,target_id,session_id,retention_local_ok,retention_eligible,root_run_id,id) WHERE finished_at>0 AND session_id<>'';
CREATE INDEX runs_experiment_current ON runs(scope,target_id,source_experiment_id,source_instance_id,created_at,id) WHERE status IN ('queued','running','stopping');
CREATE INDEX runs_experiment_history ON runs(scope,target_id,source_experiment_id,source_instance_id,created_at,id);
-- run_remote_pending.boot_id is the callee's remote-process boot identity (the remote Agent's own boot), never the caller's; it is not comparable to runs.incoming_remote_principal_id.
CREATE TABLE run_remote_pending(scope TEXT NOT NULL,owner_run_id TEXT NOT NULL,root_run_id TEXT NOT NULL,target_id TEXT NOT NULL,child_run_id TEXT NOT NULL,call_node_id TEXT NOT NULL,boot_id TEXT NOT NULL,encoded_bytes INTEGER NOT NULL CHECK(encoded_bytes>0),phase TEXT NOT NULL DEFAULT 'open' CHECK(phase IN ('open','settled','released')),settled_disposition TEXT NOT NULL DEFAULT '',settled_at INTEGER NOT NULL DEFAULT 0,released_at INTEGER NOT NULL DEFAULT 0,owner_session_id TEXT NOT NULL,CHECK((phase='open')=(settled_disposition='' AND settled_at=0 AND released_at=0)),CHECK(phase='open' OR (settled_disposition<>'' AND settled_at>0)),CHECK((phase='released')=(released_at>0)),PRIMARY KEY(scope,owner_run_id,target_id,child_run_id),FOREIGN KEY(scope,owner_run_id) REFERENCES runs(scope,id));
CREATE INDEX run_remote_pending_target ON run_remote_pending(scope,target_id,owner_run_id,child_run_id,root_run_id,call_node_id,boot_id,encoded_bytes,phase,settled_disposition,settled_at,released_at);
CREATE INDEX run_remote_pending_root ON run_remote_pending(scope,root_run_id,owner_run_id);
CREATE INDEX run_remote_pending_root_open ON run_remote_pending(scope,root_run_id,owner_run_id) WHERE phase='open';
CREATE INDEX run_remote_pending_session ON run_remote_pending(scope,owner_session_id,owner_run_id) WHERE owner_session_id<>'';
CREATE UNIQUE INDEX runs_restart_predecessor_unique ON runs(scope,target_id,predecessor_run_id) WHERE predecessor_run_id <> '';
CREATE INDEX runs_restart_predecessor_live ON runs(scope,predecessor_run_id) WHERE predecessor_run_id <> '' AND finished_at = 0;
CREATE TABLE sessions(scope TEXT NOT NULL,id TEXT NOT NULL,target_id TEXT NOT NULL,predecessor_session_id TEXT NOT NULL DEFAULT '',experiment_resource_id TEXT NOT NULL,experiment_commit_id TEXT NOT NULL,run_mode TEXT NOT NULL,experiment_name TEXT NOT NULL,root_run_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('queued','open','stopping','closed','interrupted')),stop_intent_json BLOB NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN ('','stopped','failed')),error_json BLOB NOT NULL,opened_at INTEGER NOT NULL,closed_at INTEGER NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),bytes INTEGER NOT NULL CHECK(bytes>=0),failed_cleanup INTEGER NOT NULL DEFAULT 0 CHECK(failed_cleanup IN (0,1)),PRIMARY KEY(scope,id),CHECK((status IN ('queued','open','stopping'))=(closed_at=0)),CHECK((status IN ('queued','open','stopping','interrupted'))=(outcome='')),CHECK(predecessor_session_id='' OR predecessor_session_id<>id));
CREATE UNIQUE INDEX sessions_live_target ON sessions(scope,target_id) WHERE status IN ('open','stopping');
CREATE UNIQUE INDEX sessions_restart_predecessor_unique ON sessions(scope,target_id,predecessor_session_id) WHERE predecessor_session_id<>'';
CREATE UNIQUE INDEX sessions_restart_queued_target ON sessions(scope,target_id) WHERE status='queued';
CREATE INDEX sessions_opened ON sessions(scope,opened_at,id);
CREATE INDEX sessions_target ON sessions(scope,target_id,opened_at,id);
CREATE INDEX sessions_experiment ON sessions(scope,experiment_resource_id,opened_at,id);
CREATE TABLE recordings(scope TEXT NOT NULL,id TEXT NOT NULL,session_id TEXT NOT NULL,run_id TEXT NOT NULL,experiment_resource_id TEXT NOT NULL,kind TEXT NOT NULL,archive_class TEXT NOT NULL CHECK(archive_class IN ('rosbag','screen','image-gallery','other')),path TEXT NOT NULL,summary_json BLOB NOT NULL,metadata_json BLOB NOT NULL,sort_at INTEGER NOT NULL,created_at INTEGER NOT NULL,bytes INTEGER NOT NULL CHECK(bytes>=0),PRIMARY KEY(scope,id),CHECK(session_id='' OR experiment_resource_id<>''));
CREATE INDEX recordings_created ON recordings(scope,sort_at,id);
CREATE INDEX recordings_class ON recordings(scope,archive_class,sort_at,id);
CREATE INDEX recordings_kind ON recordings(scope,kind,sort_at,id);
CREATE INDEX recordings_experiment ON recordings(scope,experiment_resource_id,sort_at,id) WHERE experiment_resource_id<>'';
CREATE INDEX recordings_experiment_class ON recordings(scope,experiment_resource_id,archive_class,sort_at,id) WHERE experiment_resource_id<>'';
CREATE INDEX recordings_experiment_data ON recordings(scope,experiment_resource_id,sort_at,id) WHERE experiment_resource_id<>'' AND archive_class<>'image-gallery';
CREATE INDEX recordings_session ON recordings(scope,session_id,sort_at,id) WHERE session_id<>'';
CREATE INDEX recordings_session_class ON recordings(scope,experiment_resource_id,session_id,archive_class,sort_at,id) WHERE session_id<>'';
CREATE INDEX recordings_session_data ON recordings(scope,experiment_resource_id,session_id,sort_at,id) WHERE session_id<>'' AND archive_class<>'image-gallery';
CREATE INDEX recordings_run ON recordings(scope,run_id,sort_at,id);
